    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) public {
        vm.assume(user != address(0));
        vm.assume(amount > 0 && amount < type(uint256).max / 1e18);
        vm.assume(interest > 0 && interest < 1e18);
        vm.assume(loanToCollateral > 0 && loanToCollateral < type(uint256).max / amount);
        vm.assume(duration > 0 && duration < 365 days * 100);

        // Arrange: deploy a minimal ERC20 mock for collateral and debt
        MockERC20 collateralToken = new MockERC20();
        MockERC20 debtToken = new MockERC20();
        collateralToken.mint(user, type(uint128).max);
        debtToken.mint(user, type(uint128).max);

        // Generate a cooler using the factory
        CoolerFactory factory = c.factory();
        vm.prank(user);
        factory.generateCooler(ERC20(address(collateralToken)), ERC20(address(debtToken)));
        address coolerAddr = factory.created(c);
        if (coolerAddr == address(0)) {
            // No cooler matched; skip this fuzz input
            return;
        }

        // Load the cloned C at the generated address
        C cooler = C(coolerAddr);

        // Retrieve the real owner (first immutable arg) and the collateral address
        address actualOwner;
        address actualCollateral;
        try cooler.owner() returns (address o) {
            actualOwner = o;
        } catch {
            return;
        }
        try cooler.collateral() returns (ERC20 co) {
            actualCollateral = address(co);
        } catch {
            return;
        }

        // The correct invariant: owner is NOT equal to collateral
        // The bug makes owner() return the collateral address, so they become equal.
        // We assert they are not equal (true for reference, false for mutant).
        assertTrue(actualOwner != actualCollateral);
    }
}

