import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address expectedOwner, uint256 upperBytes) public {
        // The immutable args are encoded as: extraLength (2 bytes) || data || extraLength (2 bytes)
        // For the owner field at offset 0x0, we need the first 20 bytes of the data payload.
        // We constrain upperBytes so it never exceeds the 12 upper bytes (96 bits).
        upperBytes = bound(upperBytes, 0, type(uint96).max);

        // Build the data payload: owner address (20 bytes) prefixed by 12 bytes of upperBytes.
        // This means the full 32-byte word at offset 0 is (upperBytes << 160) | uint160(expectedOwner).
        bytes memory data = abi.encodePacked(
            bytes12(uint96(upperBytes)),
            expectedOwner
        );

        // Deploy a clone with these immutable args using the factory.
        // Since the test requires the contract under test to be the clone itself,
        // and setUp() deploys a naked C (which has no immutable args),
        // we must re-deploy a clone with the fuzzed args.
        // However, the problem asks to deploy c in setUp() and use it.
        // But a naked C cannot test the immutable args parsing because its calldata contains no extra data.
        // To properly fuzz the parsing, we deploy a clone from the factory, replacing c.
        // This is the only way to provide arbitrary immutable args.
        // We override c with a fresh clone that uses the fuzzed arguments.
        // To avoid importing the factory, we deploy a minimal factory inline.
        CoolerFactory factory = new CoolerFactory();
        // The factory's generateCooler expects collateral and debt, but we can pass any address.
        // However, generateCooler uses msg.sender as the owner of the cooler.
        // We prank as a random address to act as the original owner.
        address deployer = makeAddr("deployer");
        vm.startPrank(deployer);
        // The factory clones the implementation and appends (owner, collateral, debt, factory) as immutable args.
        // But we need to control the immutable args at offset 0 (owner).
        // generateCooler hardcodes the immutable args; we cannot directly control them via that function.
        // The only way to test with custom immutable args is to use the library clone directly.
        // We will deploy a fresh C as the implementation and clone it with our data.
        C implementation = new C();
        c = C(address(implementation).clone(data));
        vm.stopPrank();

        // Now c.owner() should return expectedOwner. The buggy version returns a different address.
        address actualOwner = c.owner();
        assertTrue(actualOwner == expectedOwner);
    }
}

