    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 extraBytes) public {
        // The bug manifests when the upper 12 bytes of the first immutable-arg word are non-zero.
        // Forge fuzzes us a value that will be placed in those upper bytes.
        // We construct calldata that encodes the owner address in the correct position.
        // The immutable-args layout for C is:
        //   offset 0x00 (32 bytes): owner
        //   offset 0x14 (32 bytes): collateral
        //   offset 0x28 (32 bytes): debt
        //   offset 0x3c (32 bytes): factory
        // We want the first word to have the upper 12 bytes set to the fuzzed value,
        // and the lower 20 bytes to be a real address. We set owner = address(this) for simplicity.
        // We then clone C using the factory, and call owner() on the clone.

        address realOwner = address(this);
        address collateralAddr = address(0x1000000000000000000000000000000000000001);
        address debtAddr = address(0x2000000000000000000000000000000000000002);
        address factoryAddr = address(this);

        // Build the first 32-byte word: upper 12 bytes from fuzzed input, lower 20 bytes from realOwner.
        // We mask extraBytes to 12 bytes and shift it to the high position.
        uint256 upper = (extraBytes & 0xFFFFFFFFFFFFFFFFFFFFFFFF) << 160;
        uint256 firstWord = upper | uint256(uint160(realOwner));

        // Encode the immutable args packed in-place.
        bytes memory data = abi.encodePacked(
            bytes32(firstWord),       // offset 0x00
            bytes32(uint256(uint160(collateralAddr))), // offset 0x14
            bytes32(uint256(uint160(debtAddr))),       // offset 0x28
            bytes32(uint256(uint160(factoryAddr)))     // offset 0x3c
        );

        // Use the clone from ClonesWithImmutableArgs (imported via C.sol).
        // We need the factory to create the clone. The factory in C is CoolerFactory,
        // but we can directly use the library clone method if we import the library,
        // but the test contract only imports C. C inherits Clone, which has the immutable-args reader.
        // To get a clone with custom immutable args, we need the `clone` function from ClonesWithImmutableArgs.
        // Since the library is internal to the file, we can't call it directly.
        // Instead, we deploy a minimal factory that clones c with our data.
        // Wait, the test uses `new C()` in setUp, so c is the implementation, not a clone.
        // We need a clone with custom immutable args. We can deploy a helper factory contract.
        // But the rules forbid re-declaring C or importing extra files.
        // We can use low-level assembly to clone and set immutable args, but that's complex.
        // Simpler: we can use the ClonesWithImmutableArgs library if we redeclare it? No, re-declare/copy C is forbidden.
        // However, the test environment already has the library compiled because C inherits Clone which uses it.
        // The library is not directly accessible, but we can create a tiny helper that calls the library.
        // The rules allow minimal helper contracts AFTER InvMutTest. So we create a helper that clones C.
        // But the helper needs to import C to know its type. Importing C in the helper? The file already imports C for InvMutTest.
        // We can define the helper in the same file, and it can use C and ClonesWithImmutableArgs if we include the library.
        // However, the problem says: "do NOT re-declare/copy/import C. You MAY define minimal helper contract(s) AFTER InvMutTest".
        // So our helper can be defined below, and it can use C and ClonesWithImmutableArgs because they are already imported/available in the file context.
        // But we are to output ONLY the file content, and we already have `import {C} from ...` which pulls the whole file.
        // The library ClonesWithImmutableArgs is in that file, so it's available.
        // We'll define a helper contract `CloneFactory` that creates a clone with given data.
